type Exp = u128;
struct BlockSimulator {
    pub left_tape: Vec<BlockSymbol>,
    pub right_tape: Vec<BlockSymbol>,
    pub state: HigherState,
    pub base_steps: u128,
    pub self_steps: u64,
}
impl fmt::Display for BlockSymbol {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use colored::Colorize;
        use BlockSymbol::*;
        let s0 = match *self {
            Run(t, _) => &format!("{:?}", t),
            _ => &format!("{:?}", self),
        };
        let s1 = match *self {
            Run(t, _) => {
                use RunSymbolType::*;
                match t {
                    X => s0.cyan().bold(),
                    U => s0.blue(),
                    Y => s0.green().bold(),
                }
            },
            // D => s0.purple(),
            L | R => s0.dimmed(),
            _ => s0.clone().into(),
        };
        let s_exp = match *self {
            Run(_, n) => if n == 1 { "" } else { &format!("^{}", n) }
            _ => "",
        };
        write!(f, "{}{}", s1, s_exp)
    }
}

// End of customizable code

const N_RIGHTB_Y: Exp = 4;
const N_RIGHTC_Y: Exp = 2;

impl BlockSimulator {
    pub fn new() -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L],
            right_tape: vec![R, Run(Y, 1)],
            state: HigherState::LeftA1,
            base_steps: 2,
            self_steps: 0
        }
    }

    pub fn new_with_tape(left_tape: Vec<BlockSymbol>, state: HigherState, right_tape: Vec<BlockSymbol>) -> Self {
        Self {
            left_tape, right_tape, state,
            base_steps: 0,
            self_steps: 0
        }
    }

    fn try_right_Y(&mut self) -> Option<Exp> {
        match (&self.state, self.right_tape.as_mut_slice()) {
            (HigherState::RightB | HigherState::RightC, [.., BlockSymbol::Run(RunSymbolType::Y, n @ 2..)]) => {
                let n_cycles = *n / 2;
                if *n % 2 == 1 {
                    *n = 1;
                } else {
                    self.right_tape.pop();
                }
                add_or_merge_run(&mut self.left_tape, RunSymbolType::U, n_cycles*2);
                Some((N_RIGHTB_Y + N_RIGHTC_Y) * n_cycles)
            },
            _ => None,
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        if self.state == HigherState::LeftB && self.left_tape == vec![BlockSymbol::L] {
            self.base_steps += 1; // ??
            self.self_steps += 1;
            return Err(SimError::Halted);
        }

        if let Some(new_base_steps) = self.try_right_Y() {
            self.base_steps = self.base_steps.checked_add(new_base_steps).unwrap();
            self.self_steps += 1;
            return Ok(())
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }

    pub fn is_basic_state(&self) -> bool {
        use BlockSymbol::*;
        use RunSymbolType::*;
        use HigherState::*;
        if matches!(self.state, LeftA1 | LeftA2 | LeftB) {
            return (&self.left_tape).iter().all(|s| matches!(s, L | P2 | Run(X, _)));
        }
        false
    }

    pub fn parse_halt_state(&self) -> Option<Exp> {
        use BlockSymbol::*;
        if self.state == HigherState::LeftB && self.left_tape == vec![L] {
            if let [R, Run(RunSymbolType::Y, n)] = self.right_tape.as_slice() {
                return Some(n + 1) // nonzero symbols include a 2 in each of the Y and the 1 in the L
            }
        }
        None
    }

    pub fn parse_special_state(&self) -> Option<(Exp, Exp)> {
        use BlockSymbol::*;
        use RunSymbolType::*;
        use HigherState::*;
        if self.state == LeftA1
        && (&self.left_tape).iter().all(|s| matches!(s, L | P2 | Run(X, _)))
        && (&self.right_tape).iter().all(|s| matches!(s, Run(Y, _) | R)) {
            let mut a = 0;
            for s in &self.left_tape {
                match s {
                    P2 => a += 1,
                    Run(X, n) => a += 2*n,
                    _ => (),
                }
            }

            let mut c = 0;
            for s in &self.right_tape {
                if let Run(Y, n) = s {
                    c += n;
                }
            }
            Some((a, c))
        } else {
            None
        }
    }

    pub fn new_from_special_state(a: Exp, c: Exp) -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        let left_tape = if a == 0 {
            vec![L]
        } else if a == 1 {
            vec![L, P2]
        } else if a % 2 == 0 {
            vec![L, Run(X, a/2)]
        } else {
            vec![L, P2, Run(X, a/2)]
        };
        let right_tape = vec![R, Run(Y, c)];
        Self::new_with_tape(left_tape, HigherState::LeftA1, right_tape)
    }
}

enum SpecialState {
    A { a: Exp, c: Exp },
    Halt(Exp)
}

fn check_rule_example(a0: Exp, c0: Exp, expect: SpecialState) -> Result<(), ()> {
    const MAX_STEPS: u32 = 1000;
    let mut sim = BlockSimulator::new_from_special_state(a0, c0);

    match expect {
        SpecialState::A { a: a_exp, c: c_exp } => {
            for i in 1..=MAX_STEPS {
                let res = sim.step();
                if let Some((a, c)) = sim.parse_special_state() {
                    if a == a_exp && c == c_exp {
                        println!("A({}, {}) => A({}, {})", a0, c0, a_exp, c_exp);
                        return Ok(());
                    }
                }
                if res.is_err() {
                    println!("A({}, {}) => {:?}; {}", a0, c0, res, sim);
                    return Err(());
                }
            }
        }
        SpecialState::Halt(n_exp) => {
            for i in 1..=MAX_STEPS {
                let res = sim.step();
                match res {
                    Ok(_) => (),
                    Err(SimError::Halted) => {
                        if let Some(n) = sim.parse_halt_state() {
                            if n == n_exp {
                                println!("A({}, {}) => Halt({})", a0, c0, n_exp);
                                return Ok(());
                            } else {
                                println!("A({}, {}) => Halt({}) but expected Halt({})", a0, c0, n, n_exp);
                                return Err(());
                            }
                        }
                    }
                    Err(SimError::UndefinedTransition) => {
                        println!("A({}, {}) => undefined {}", a0, c0, sim);
                        return Err(());
                    }
                }
                if res.is_err() {
                    println!("A({}, {}) => {:?}; {}", a0, c0, res, sim);
                    return Err(());
                }
            }
        }
    }

    println!("A({}, {}) => out of time; {}", a0, c0, sim);
    Err(())
}

fn check_rules_a() {
    for c in (2..=10).step_by(2) {
        for delta in 1..=5 {
            let a = c + delta;
            if check_rule_example(a, c, SpecialState::A { a: a-c-1, c: 3*c/2 + 2 }).is_err() {
                println!("oh no");
                return;
            }
        }
    }
}

